app.put("/api/v1/restores/json/resources/:id", async (c) => {
  const userOnly = requireUser(c);
  if (userOnly) {
    return userOnly;
  }
  const form = await c.req.raw.formData();
  const file2 = form.get("file");
  const metadataValue = form.get("metadata");
  if (!(file2 instanceof File) || typeof metadataValue !== "string") {
    return badRequest(c, "Restore resource file and metadata are required.");
  }
  let metadataInput;
  try {
    metadataInput = JSON.parse(metadataValue);
  } catch {
    return badRequest(c, "Restore resource metadata must be valid JSON.");
  }
  const parsed = JsonBackupResourceMetadataSchema.safeParse(metadataInput);
  if (!parsed.success || parsed.data.id !== c.req.param("id")) {
    return badRequest(c, "Restore resource metadata is invalid.");
  }
  const metadata = parsed.data;
  const memo = await getMemoDetail(c.env.DB, getWorkspaceId(c), metadata.memoId);
  if (!memo) {
    return notFound(c, "Restore target memo not found.");
  }
  const maxBytes = metadata.kind === "image" ? MAX_IMAGE_UPLOAD_BYTES : MAX_ATTACHMENT_UPLOAD_BYTES;
  if (file2.size <= 0 || file2.size > maxBytes) {
    return apiError(c, "upload_too_large", "Backup resource size is invalid.", 413);
  }
  const filename = normalizeFilename(metadata.filename || file2.name) || `${metadata.kind}-${metadata.id}`;
  const objectKey = `workspaces/${getWorkspaceId(c)}/restores/${metadata.memoId}/${metadata.id}/${Date.now()}-${filename}`;
  const bytes = new Uint8Array(await file2.arrayBuffer());
  const foreignResource = await c.env.DB.prepare(`SELECT r.id FROM resources r INNER JOIN memos m ON m.id = r.memo_id
     WHERE r.id = ? AND m.workspace_id <> ? LIMIT 1`).bind(metadata.id, getWorkspaceId(c)).first();
  if (foreignResource) {
    return conflict(c, "cross_workspace_id_conflict", "Backup resource ID is already used by another user.");
  }
  const previous = await c.env.DB.prepare(`SELECT r.object_key FROM resources r INNER JOIN memos m ON m.id = r.memo_id WHERE r.id = ? AND m.workspace_id = ?`).bind(metadata.id, getWorkspaceId(c)).first();
  const originalMemo = metadata.originalMemoId ? await c.env.DB.prepare(`SELECT id FROM memos WHERE id = ? AND workspace_id = ?`).bind(metadata.originalMemoId, getWorkspaceId(c)).first() : null;
  await c.env.RESOURCES.put(objectKey, bytes, {
    httpMetadata: { contentType: metadata.mimeType ?? file2.type ?? "application/octet-stream" },
    customMetadata: { memoId: metadata.memoId, resourceId: metadata.id, restored: "true" }
  });
  try {
    const now = isoNow();
    await c.env.DB.prepare(`INSERT INTO resources (
        id, memo_id, original_memo_id, bucket_name, object_key, kind, mime_type, filename,
        byte_size, sha256, width, height, metadata_json, is_deleted, created_at, updated_at, deleted_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, NULL)
      ON CONFLICT(id) DO UPDATE SET
        memo_id = excluded.memo_id,
        original_memo_id = excluded.original_memo_id,
        bucket_name = excluded.bucket_name,
        object_key = excluded.object_key,
        kind = excluded.kind,
        mime_type = excluded.mime_type,
        filename = excluded.filename,
        byte_size = excluded.byte_size,
        sha256 = excluded.sha256,
        width = excluded.width,
        height = excluded.height,
        metadata_json = excluded.metadata_json,
        is_deleted = 0,
        updated_at = excluded.updated_at,
        deleted_at = NULL`).bind(metadata.id, metadata.memoId, originalMemo?.id ?? null, c.env.EDGE_EVER_R2_BUCKET_NAME?.trim() || DEFAULT_R2_BUCKET_NAME, objectKey, metadata.kind, metadata.mimeType ?? file2.type ?? null, filename, bytes.byteLength, await sha256Bytes(bytes), metadata.width, metadata.height, JSON.stringify({ source: "edgeever-zip-import" }), metadata.createdAt, now).run();
  } catch (error51) {
    await c.env.RESOURCES.delete(objectKey);
    throw error51;
  }
  if (previous?.object_key && previous.object_key !== objectKey) {
    await c.env.RESOURCES.delete(previous.object_key);
  }
  return c.json({ ok: true });
});
