var createSession = async (c, user) => {
  const token = randomToken(SESSION_TOKEN_BYTES);
  const id = createId("sess");
  const now = isoNow();
  const maxAge = getSessionMaxAge(c.env);
  const expiresAt = new Date(Date.now() + maxAge * 1000).toISOString();
  const ip = c.req.header("CF-Connecting-IP");
  const ipHash = ip ? await sha2562(ip) : null;
  await c.env.DB.prepare(`INSERT INTO sessions (
      id, user_id, token_hash, user_agent, ip_hash, expires_at, created_at, last_seen_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`).bind(id, user.id, await sha2562(token), c.req.header("User-Agent") ?? null, ipHash, expiresAt, now, now).run();
  return { id, token, maxAge };
};
