var moveMemosToNotebook = async (db, workspaceId, memoIds, notebookId, actor, actorLabel) => {
  const uniqueMemoIds = Array.from(new Set(memoIds));
  if (uniqueMemoIds.length === 0) {
    return 0;
  }
  const placeholders = uniqueMemoIds.map(() => "?").join(", ");
  const rows = await db.prepare(`SELECT id, notebook_id
       FROM memos
       WHERE workspace_id = ? AND is_deleted = 0 AND id IN (${placeholders})`).bind(workspaceId, ...uniqueMemoIds).all();
  if (rows.results.length !== uniqueMemoIds.length) {
    throw new AppError("missing_memos", "One or more memos cannot be moved.", 400);
  }
  const now = isoNow();
  const statements = [
    db.prepare(`UPDATE memos
         SET notebook_id = ?, updated_by = ?, updated_at = ?
         WHERE workspace_id = ? AND is_deleted = 0 AND id IN (${placeholders})`).bind(notebookId, actorLabel, now, workspaceId, ...uniqueMemoIds)
  ];
  for (const row of rows.results) {
    statements.push(auditStatement(db, actor.actorType, actor.actorId, "memo.move", "memo", row.id, {
      fromNotebookId: row.notebook_id,
      toNotebookId: notebookId
    }));
  }
  await db.batch(statements);
  return uniqueMemoIds.length;
};
